    {"surface": "常務取締役", "reading": "じょうむとりしまりやく", "vi_short": "Giám đốc thường trực", "vi_explanation": "Thành viên HĐQT giữ vị trí quản lý các công việc thường nhật của công ty, đứng dưới Tổng giám đốc và Giám đốc điều hành cấp cao.", "en_preferred": "Managing Director", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": ['常務'], "antonyms": [], "related_terms": ['専務取締役', '代表取締役']},
    {"surface": "専務取締役", "reading": "せんむとりしまりやく", "vi_short": "Giám đốc điều hành cấp cao / Phó tổng giám đốc thứ nhất", "vi_explanation": "Chức vụ lãnh đạo hỗ trợ trực tiếp cho Tổng giám đốc, phụ trách toàn diện các mảng nghiệp vụ cốt lõi của công ty.", "en_preferred": "Senior Managing Director / Executive VP", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": ['専務'], "antonyms": [], "related_terms": ['常務取締役', '代表取締役']},
    {"surface": "取締役会議事録", "reading": "とりしまりやくかいぎじろく", "vi_short": "biên bản cuộc họp Hội đồng quản trị", "vi_explanation": "Văn bản pháp lý ghi chép trung thực toàn bộ diễn biến, ý kiến thảo luận và kết quả biểu quyết các nghị quyết trong phiên họp HĐQT.", "en_preferred": "Minutes of Board of Directors meeting", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['取締役会', '商業登記', '署名捺印']},
    {"surface": "定時株主総会", "reading": "ていじかぶぬしそうかい", "vi_short": "Đại hội đồng cổ đông thường niên", "vi_explanation": "Cuộc họp định kỳ hàng năm tổ chức trong vòng 3 tháng sau ngày khóa sổ tài chính để báo cáo kết quả và bầu cử nhân sự.", "en_preferred": "Annual General Meeting of Shareholders (AGM)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": ['臨時株主総会'], "related_terms": ['招集通知', '決算報告']},
    {"surface": "臨時株主総会", "reading": "りんじかぶぬしそうかい", "vi_short": "Đại hội đồng cổ đông bất thường", "vi_explanation": "Cuộc họp cổ đông được triệu tập đột xuất khi có các vấn đề quan trọng cần thông qua ngay như sáp nhập hoặc tăng vốn khẩn cấp.", "en_preferred": "Extraordinary General Meeting of Shareholders", "tier": "PRO-A2", "priority": 91, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": ['定時株主総会'], "related_terms": ['議決権', '特別決議']},
    {"surface": "招集通知", "reading": "しょうしゅうちつ", "vi_short": "thư mời họp cổ đông / thông báo triệu tập cuộc họp", "vi_explanation": "Văn bản gửi cho các cổ đông nêu rõ thời gian, địa điểm, chương trình nghị sự và các tờ trình biểu quyết của đại hội cổ đông.", "en_preferred": "Notice of convocation of shareholders meeting", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['株主総会', '議決権行使書']},
    {"surface": "議決権", "reading": "ぎけつけん", "vi_short": "quyền biểu quyết của cổ đông", "vi_explanation": "Quyền năng của cổ đông được bỏ phiếu tán thành hoặc phản đối các nghị quyết đưa ra tại cuộc họp Đại hội đồng cổ đông.", "en_preferred": "Voting rights", "tier": "PRO-A2", "priority": 95, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['株式数', '委任状', '議決権行使']},
    {"surface": "株主名簿", "reading": "かぶぬしめいぼ", "vi_short": "sổ đăng ký cổ đông", "vi_explanation": "Sổ sách pháp lý lưu trữ danh sách họ tên, địa chỉ và số lượng cổ phần sở hữu của từng cổ đông trong công ty.", "en_preferred": "Shareholder registry", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['名義書換', '配当金基準日']},
    {"surface": "委任状", "reading": "いにんじょう", "vi_short": "giấy ủy quyền", "vi_explanation": "Văn bản trao quyền cho người khác đại diện cho mình thực hiện các hành vi pháp lý (như đi họp cổ đông bỏ phiếu thay, ký giấy tờ).", "en_preferred": "Power of attorney / Proxy", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['代理人', '委任事項']},
    {"surface": "善管注意義務", "reading": "ぜんかんちゅういぎむ", "vi_short": "nghĩa vụ của người quản lý mẫn cán", "vi_explanation": "Nghĩa vụ pháp lý của giám đốc phải điều hành công ty với sự cẩn trọng và trách nhiệm cao nhất mà một người có chuyên môn phải có.", "en_preferred": "Duty of care of a good manager", "tier": "PRO-A3", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['取締役', '忠実義務', '会社法']},
    {"surface": "忠実義務", "reading": "ちゅうじつぎむ", "vi_short": "nghĩa vụ trung thành với lợi ích công ty", "vi_explanation": "Nguyên tắc buộc giám đốc phải đặt lợi ích của công ty lên trên lợi ích cá nhân, cấm trục lợi hoặc tư lợi cá nhân.", "en_preferred": "Duty of loyalty", "tier": "PRO-A3", "priority": 91, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['善管注意義務', '利益相反取引']},
    {"surface": "競業避止義務", "reading": "きょうぎょうひしぎむ", "vi_short": "nghĩa vụ không cạnh tranh với công ty", "vi_explanation": "Quy định cấm giám đốc hoặc nhân sự chủ chốt mở công ty kinh doanh cùng ngành hoặc làm việc cho đối thủ cạnh tranh.", "en_preferred": "Non-compete obligation", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['取締役', '秘密保持', '同業他社']},
    {"surface": "内部統制", "reading": "ないぶとうせい", "vi_short": "hệ thống kiểm soát nội bộ (Internal Control)", "vi_explanation": "Quy trình và chính sách được thiết lập trong toàn doanh nghiệp nhằm bảo đảm tính chính xác của báo cáo tài chính và tuân thủ luật pháp.", "en_preferred": "Internal control", "tier": "PRO-A2", "priority": 95, "source_reference": "trade_business_corpus:governance", "synonyms": ['J-SOX'], "antonyms": [], "related_terms": ['内部監査', '業務フロー']},
    {"surface": "コンプライアンス", "reading": "こんぷらいあんす", "vi_short": "tuân thủ pháp luật và đạo đức kinh doanh", "vi_explanation": "Việc doanh nghiệp và nhân viên chấp hành nghiêm chỉnh luật pháp, quy chế nội bộ và các chuẩn mực đạo đức xã hội.", "en_preferred": "Compliance", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:governance", "synonyms": ['法令遵守'], "antonyms": [], "related_terms": ['内部通報', '企業倫理']},
    {"surface": "内部通報制度", "reading": "ないぶつうほうせいど", "vi_short": "cơ chế tố giác nội bộ (Whistleblowing)", "vi_explanation": "Kênh tiếp nhận bí mật các thông tin tố cáo sai phạm, hối lộ hoặc quấy rối trong công ty, được pháp luật bảo vệ không bị trừng phạt.", "en_preferred": "Whistleblower system", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": ['ヘルプライン'], "antonyms": [], "related_terms": ['公益通報者保護法', '不正防止']},
    {"surface": "利益相反取引", "reading": "りえきそうはんとりひき", "vi_short": "giao dịch xung đột lợi ích giữa giám đốc và công ty", "vi_explanation": "Giao dịch mua bán giữa cá nhân giám đốc và chính công ty mình đang điều hành, bắt buộc phải có sự chấp thuận trước của HĐQT.", "en_preferred": "Conflict-of-interest transaction", "tier": "PRO-A3", "priority": 90, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['取締役会承認', '忠実義務']},
    {"surface": "コーポレートガバナンス", "reading": "こーぽれーとがばなんす", "vi_short": "quản trị công ty / quản trị doanh nghiệp minh bạch", "vi_explanation": "Cơ chế kiểm soát, giám sát bộ máy điều hành công ty nhằm đảm bảo tính công khai, bảo vệ lợi ích của cổ đông và đối tác.", "en_preferred": "Corporate governance", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:governance", "synonyms": ['企業統治'], "antonyms": [], "related_terms": ['内部統制', '社外取締役']},
    {"surface": "稟議書", "reading": "りんぎしょ", "vi_short": "tờ trình phê duyệt nội bộ (Ringisho)", "vi_explanation": "Tài liệu đề xuất kế hoạch kinh doanh hoặc chi tiêu xin ý kiến chữ ký xét duyệt lần lượt qua các cấp quản lý trước khi triển khai.", "en_preferred": "Internal approval request / Ringi proposal", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:governance", "synonyms": ['稟議'], "antonyms": [], "related_terms": ['決裁', '根回し', '起案']},
    {"surface": "決裁", "reading": "けっさい", "vi_short": "quyết định phê duyệt chính thức của cấp có thẩm quyền", "vi_explanation": "Hành động người có thẩm quyền cao nhất (như Tổng giám đốc) ký tên hoặc đóng dấu phê duyệt thông qua một đề xuất.", "en_preferred": "Final approval / Sanction", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['稟議書', '承認', '決裁権限']},
    {"surface": "職務権限規程", "reading": "しょくむけんげんきてい", "vi_short": "quy chế phân quyền chức vụ", "vi_explanation": "Văn bản nội bộ quy định rõ ràng hạn mức số tiền và phạm vi công việc mà từng cấp chức vụ (Trưởng phòng, Giám đốc) được quyền tự quyết định.", "en_preferred": "Regulations on administrative authority", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['決裁', '業務分掌']},
    {"surface": "定款", "reading": "ていかん", "vi_short": "điều lệ công ty", "vi_explanation": "Văn kiện pháp lý nền tảng tối cao của doanh nghiệp, quy định tên gọi, ngành nghề hoạt động, cơ cấu tổ chức và vốn góp.", "en_preferred": "Articles of Incorporation / Charter", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['商業登記', '公証人認証']},
    {"surface": "商業登記", "reading": "しょうぎょうとうき", "vi_short": "đăng ký kinh doanh / đăng ký doanh nghiệp tại Sở Tư pháp", "vi_explanation": "Thủ tục đăng ký công khai các thông tin pháp lý của doanh nghiệp (vốn, người đại diện, trụ sở) vào sổ bạ của Sở Tư pháp Nhật Bản.", "en_preferred": "Commercial registration", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['法務局', '履歴事項全部証明書']},
    {"surface": "履歴事項全部証明書", "reading": "りれきじこうぜんぶしょうめいしょ", "vi_short": "giấy chứng nhận đăng ký doanh nghiệp bản đầy đủ (Toukicho)", "vi_explanation": "Văn bản do Pháp vụ cục (Sở Tư pháp) cấp, chứng minh tư cách pháp nhân, danh sách giám đốc và lịch sử thay đổi của công ty.", "en_preferred": "Certificate of all registered historical matters (Company registry)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:governance", "synonyms": ['登記簿謄本'], "antonyms": [], "related_terms": ['商業登記', '法務局', '印鑑証明書']},
    {"surface": "印鑑証明書", "reading": "いんかんしょうめいしょ", "vi_short": "giấy chứng nhận con dấu pháp nhân", "vi_explanation": "Văn bản chính thức do cơ quan đăng ký cấp để xác nhận con dấu đóng trên hợp đồng là con dấu hợp pháp đã đăng ký của công ty.", "en_preferred": "Seal registration certificate", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:governance", "synonyms": [], "antonyms": [], "related_terms": ['代表者印', '実印', '契約締結']},
    {"surface": "契約書", "reading": "けいやくしょ", "vi_short": "văn bản hợp đồng", "vi_explanation": "Văn bản thỏa thuận pháp lý giữa hai hay nhiều bên, xác lập quyền và nghĩa vụ ràng buộc có giá trị cưỡng chế thi hành.", "en_preferred": "Contract / Written agreement", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['契約締結', '甲乙', '押印']},
    {"surface": "秘密保持契約", "reading": "ひみつほじけいやく", "vi_short": "thỏa thuận bảo mật thông tin (NDA)", "vi_explanation": "Hợp đồng ký kết giữa các bên nhằm cam kết không tiết lộ các bí mật kinh doanh, kỹ thuật, tài chính cho bất kỳ bên thứ ba nào.", "en_preferred": "Non-Disclosure Agreement (NDA)", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:legal", "synonyms": ['NDA'], "antonyms": [], "related_terms": ['守秘義務', '秘密情報']},
    {"surface": "業務委託契約書", "reading": "ぎょうむいたくけいやくしょ", "vi_short": "hợp đồng thuê khoán ngoài / dịch vụ ủy thác", "vi_explanation": "Hợp đồng thỏa thuận giao cho một đơn vị hoặc cá nhân bên ngoài thực hiện một công việc cụ thể để nhận thù lao.", "en_preferred": "Service agreement / Outsourcing contract", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['委託者', '受託者', '成果物']},
    {"surface": "雇用契約書", "reading": "こようけいやくしょ", "vi_short": "hợp đồng lao động", "vi_explanation": "Văn bản pháp lý ký kết giữa người sử dụng lao động và người lao động, xác định quyền hạn, tiền lương và điều kiện làm việc.", "en_preferred": "Employment contract", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:legal", "synonyms": ['労働契約書'], "antonyms": [], "related_terms": ['労働条件通知書', '就業規則']},
    {"surface": "賃貸借契約書", "reading": "ちんたいしゃくけいやくしょ", "vi_short": "hợp đồng thuê tài sản / thuê văn phòng", "vi_explanation": "Hợp đồng quy định việc chủ sở hữu trao quyền sử dụng văn phòng, máy móc hoặc nhà xưởng cho bên thuê để nhận tiền thuê định kỳ.", "en_preferred": "Lease agreement / Rental contract", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['賃料', '敷金', '原状回復']},
    {"surface": "売買契約書", "reading": "ばいばいけいやくしょ", "vi_short": "hợp đồng mua bán hàng hóa", "vi_explanation": "Hợp đồng chuyển giao quyền sở hữu tài sản hoặc hàng hóa từ người bán sang người mua với một mức giá tiền thỏa thuận.", "en_preferred": "Sales contract / Purchase contract", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['所有権移転', '引渡し', '代金支払']},
    {"surface": "合意書", "reading": "ごういしょ", "vi_short": "văn bản thỏa thuận / thỏa thuận ghi nhớ", "vi_explanation": "Văn bản ghi nhận sự thống nhất ý chí giữa hai bên về một số điều khoản hợp tác cụ thể trong kinh doanh.", "en_preferred": "Written agreement / Accord", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['覚書', '契約書']},
    {"surface": "覚書", "reading": "おぼえがき", "vi_short": "phụ lục thỏa thuận bổ sung / bản ghi nhớ (MOU)", "vi_explanation": "Văn bản bổ sung, làm rõ hoặc thay đổi một số điều khoản đã ký trong hợp đồng chính mà không cần ký lại toàn bộ hợp đồng.", "en_preferred": "Memorandum of Understanding (MOU) / Addendum", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": ['MOU'], "antonyms": [], "related_terms": ['合意書', '基本契約']},
    {"surface": "契約締結", "reading": "けいやくていけつ", "vi_short": "ký kết hợp đồng chính thức", "vi_explanation": "Hành động các bên đại diện pháp luật cùng ký tên và đóng dấu vào bản hợp đồng để hợp đồng bắt đầu phát sinh hiệu lực.", "en_preferred": "Execution of contract / Signing a contract", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['署名捺印', '契約書']},
    {"surface": "甲乙関係", "reading": "こうおつかんけい", "vi_short": "quan hệ các bên ký kết (Bên A - Bên B)", "vi_explanation": "Cách gọi quy ước theo tiếng Nhật để định danh bên thứ nhất là Giáp (甲 - bên A) và bên thứ hai là Ất (乙 - bên B) trong văn bản pháp luật.", "en_preferred": "Parties relationship (Party A and Party B)", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['甲', '乙', '丙']},
    {"surface": "解除権", "reading": "かいじょけん", "vi_short": "quyền đơn phương chấm dứt hợp đồng", "vi_explanation": "Quyền năng của một bên được quyền hủy bỏ hợp đồng khi đối tác vi phạm nghiêm trọng nghĩa vụ cam kết.", "en_preferred": "Right of termination / Cancellation right", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['債務不履行', '契約解除']},
    {"surface": "契約不適合責任", "reading": "けいやくふてきごうせきにん", "vi_short": "trách nhiệm do giao hàng không đúng thỏa thuận hợp đồng", "vi_explanation": "Quy định theo Bộ luật Dân sự mới của Nhật buộc người bán phải sửa chữa, đổi mới, giảm giá hoặc bồi thường khi hàng bị lỗi sai quy cách.", "en_preferred": "Liability for non-conformity of goods", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:legal", "synonyms": ['瑕疵担保責任'], "antonyms": [], "related_terms": ['追完請求', '代金減額請求']},
    {"surface": "損害賠償請求", "reading": "そんがいばいしょうせいきゅう", "vi_short": "yêu cầu đòi bồi thường thiệt hại", "vi_explanation": "Hành động yêu cầu bên vi phạm hợp đồng hoặc bên gây thiệt hại phải chi trả tiền để bù đắp các tổn thất tài chính thực tế phát sinh.", "en_preferred": "Claim for damages", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['債務不履行', '不法行為', '免責条項']},
    {"surface": "免責条項", "reading": "めんせきじょうこう", "vi_short": "điều khoản miễn trừ trách nhiệm", "vi_explanation": "Điều khoản trong hợp đồng quy định rõ các trường hợp doanh nghiệp được miễn không phải bồi thường thiệt hại (như thiên tai, chiến tranh).", "en_preferred": "Exemption clause / Limitation of liability", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['不可抗力', '損害賠償']},
    {"surface": "不可抗力条項", "reading": "ふかこうりょくじょうこう", "vi_short": "điều khoản bất khả kháng (Force Majeure)", "vi_explanation": "Quy định miễn trừ nghĩa vụ thực hiện hợp đồng khi xảy ra các sự kiện ngoài tầm kiểm soát của con người như động đất, bão lũ, dịch bệnh.", "en_preferred": "Force majeure clause", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:legal", "synonyms": ['フォースマジュール'], "antonyms": [], "related_terms": ['免責条項', '履行不能']},
    {"surface": "準拠法", "reading": "じゅんきょほう", "vi_short": "luật áp dụng điều chỉnh hợp đồng", "vi_explanation": "Hệ thống luật pháp của quốc gia nào được các bên thống nhất lựa chọn để giải thích và xử lý khi có tranh chấp hợp đồng thương mại quốc tế.", "en_preferred": "Governing law", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['管轄裁判所', '国際契約']},
    {"surface": "管轄裁判所", "reading": "かんかつさいばんしょ", "vi_short": "tòa án có thẩm quyền xét xử tranh chấp", "vi_explanation": "Tòa án cụ thể được các bên ấn định trước trong hợp đồng để thụ lý xét xử nếu xảy ra kiện tụng không thể thương lượng hòa giải.", "en_preferred": "Court of competent jurisdiction", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['準拠法', '合意管轄', '仲裁']},
    {"surface": "知的財産権", "reading": "ちてきざいさんけん", "vi_short": "quyền sở hữu trí tuệ", "vi_explanation": "Quyền tài sản được pháp luật bảo hộ đối với các sáng tạo trí tuệ của con người (bao gồm sáng chế, nhãn hiệu, kiểu dáng, bản quyền tác giả).", "en_preferred": "Intellectual property rights (IPR)", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:legal", "synonyms": ['知財'], "antonyms": [], "related_terms": ['特許権', '著作権', '商標権']},
    {"surface": "著作権", "reading": "ちょさくけん", "vi_short": "bản quyền tác giả", "vi_explanation": "Quyền đối với các tác phẩm sáng tạo văn học, nghệ thuật, phần mềm máy tính, hình ảnh, tài liệu đào tạo.", "en_preferred": "Copyright", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['知的財産権', '著作権侵害']},
    {"surface": "特許権", "reading": "とっきょけん", "vi_short": "quyền sáng chế độc quyền", "vi_explanation": "Quyền độc quyền khai thác thương mại một sáng kiến kỹ thuật mới được Cục Sáng chế cấp bằng bảo hộ.", "en_preferred": "Patent right", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['特許出願', '特許侵害', '実施権']},
    {"surface": "商標権", "reading": "しょうひょうけん", "vi_short": "quyền sở hữu nhãn hiệu / thương hiệu", "vi_explanation": "Quyền độc quyền sử dụng logo, tên gọi sản phẩm hoặc khẩu hiệu kinh doanh đã đăng ký bảo hộ độc quyền trên thị trường.", "en_preferred": "Trademark right", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['ロゴ', '商標登録', 'ブランド']},
    {"surface": "ライセンス契約", "reading": "らいせんすけいやく", "vi_short": "hợp đồng chuyển giao quyền sử dụng (Li-xăng)", "vi_explanation": "Hợp đồng cho phép bên khác được quyền sử dụng phần mềm, công nghệ hoặc nhãn hiệu của mình để đổi lấy tiền phí bản quyền.", "en_preferred": "License agreement", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['ロイヤルティ', '実施権']},
    {"surface": "守秘義務", "reading": "しゅひぎむ", "vi_short": "nghĩa vụ bảo mật thông tin", "vi_explanation": "Nghĩa vụ pháp lý ràng buộc nhân viên hoặc đối tác không được tiết lộ thông tin nội bộ của công ty trong và sau khi chấm dứt hợp đồng.", "en_preferred": "Confidentiality obligation", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['秘密保持契約', '情報漏洩']},
    {"surface": "契約更新", "reading": "けいやくこうしん", "vi_short": "gia hạn hợp đồng", "vi_explanation": "Việc kéo dài thêm thời hạn hiệu lực của hợp đồng đã ký trước khi hợp đồng cũ hết hạn (có thể tự động hoặc ký văn bản).", "en_preferred": "Contract renewal", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['自動更新', '契約満了']},
    {"surface": "自動更新条項", "reading": "じどうこうしんじょうこう", "vi_short": "điều khoản tự động gia hạn hợp đồng", "vi_explanation": "Điều khoản quy định hợp đồng sẽ tự động gia hạn thêm 1 năm nếu không bên nào gửi thông báo bằng văn bản từ chối trước 1 tháng.", "en_preferred": "Automatic renewal clause", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['契約期間', '解約予告']},
    {"surface": "違約金", "reading": "いやくきん", "vi_short": "tiền phạt vi phạm hợp đồng", "vi_explanation": "Khoản tiền ấn định trước trong hợp đồng mà bên vi phạm cam kết phải nộp cho bên bị thiệt hại.", "en_preferred": "Penalty for breach of contract", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:legal", "synonyms": ['ペナルティ'], "antonyms": [], "related_terms": ['損害賠償', '債務不履行']},
    {"surface": "債務不履行", "reading": "さいむふりこう", "vi_short": "không thực hiện đúng nghĩa vụ hợp đồng", "vi_explanation": "Hành vi vi phạm hợp đồng khi một bên chậm bàn giao, không thanh toán tiền hoặc giao sai hàng so với cam kết.", "en_preferred": "Default / Breach of contract", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": ['履行'], "related_terms": ['損害賠償', '解除権']},
    {"surface": "反社会的勢力排除条項", "reading": "はんしゃかいてきせいりょくはいじょじょうこう", "vi_short": "điều khoản loại trừ các tổ chức xã hội đen (Boryokudan)", "vi_explanation": "Điều khoản bắt buộc trong mọi hợp đồng thương mại tại Nhật Bản cam kết không có liên hệ với các băng nhóm tội phạm xã hội đen.", "en_preferred": "Anti-social forces exclusion clause", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": ['暴排条項'], "antonyms": [], "related_terms": ['暴力団排除条例', '契約解除']},
    {"surface": "電子署名", "reading": "でんししょめい", "vi_short": "chữ ký điện tử / chữ ký số", "vi_explanation": "Dữ liệu điện tử được gắn vào văn bản hợp đồng số để chứng thực danh tính người ký và bảo đảm văn bản không bị sửa đổi.", "en_preferred": "Electronic signature / Digital signature", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": [], "antonyms": [], "related_terms": ['電子契約', 'クラウドサイン', 'タイムスタンプ']},
    {"surface": "押印", "reading": "おういん", "vi_short": "đóng dấu pháp lý vào văn bản", "vi_explanation": "Hành vi đóng con dấu chính thức của công ty vào hợp đồng hoặc tài liệu pháp lý theo truyền thống kinh doanh Nhật Bản.", "en_preferred": "Affixing a seal / Stamping", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:legal", "synonyms": ['捺印'], "antonyms": [], "related_terms": ['実印', '角印', '契約締結']},
    {"surface": "就業規則", "reading": "しゅうぎょうきそく", "vi_short": "nội quy lao động của công ty", "vi_explanation": "Bộ quy định nội bộ bắt buộc đối với công ty có từ 10 nhân viên trở lên, quy định giờ giấc làm việc, kỷ luật, chế độ thưởng phạt và nghỉ phép.", "en_preferred": "Work rules / Employment regulations", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['労働基準監督署', '労働基準法']},
    {"surface": "雇用形態", "reading": "こようけいたい", "vi_short": "hình thức sử dụng lao động", "vi_explanation": "Hình thức ký kết hợp đồng làm việc giữa công ty và nhân sự (như nhân viên chính thức, hợp đồng, phái cử hoặc bán thời gian).", "en_preferred": "Employment status / Employment type", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['正社員', '契約社員', '派遣社員']},
    {"surface": "正社員", "reading": "せいしゃいん", "vi_short": "nhân viên chính thức dài hạn", "vi_explanation": "Người lao động làm việc với hợp đồng không xác định thời hạn, hưởng đầy đủ chế độ phúc lợi và lộ trình phát triển sự nghiệp.", "en_preferred": "Regular employee / Full-time employee", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['契約社員', '派遣社員'], "related_terms": ['無期雇用', '終身雇用']},
    {"surface": "契約社員", "reading": "けいやくしゃいん", "vi_short": "nhân viên làm việc theo hợp đồng xác định thời hạn", "vi_explanation": "Người lao động được ký hợp đồng làm việc có thời hạn cụ thể (thường là 6 tháng hoặc 1 năm và được gia hạn tối đa 5 năm).", "en_preferred": "Contract employee / Fixed-term employee", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['正社員'], "related_terms": ['有期雇用', '無期転換ルール']},
    {"surface": "派遣社員", "reading": "はけんしゃいん", "vi_short": "nhân viên phái cử qua công ty cung ứng nhân lực", "vi_explanation": "Người lao động ký hợp đồng với công ty phái cử (Dispatch Agency) nhưng được cử sang làm việc thực tế tại văn phòng của công ty khách hàng.", "en_preferred": "Dispatched worker / Temp worker", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['労働者派遣法', '派遣元', '派遣先']},
    {"surface": "パートタイマー", "reading": "ぱーとたいまー", "vi_short": "nhân viên làm việc bán thời gian", "vi_explanation": "Người lao động làm việc với số giờ làm việc trong tuần ít hơn đáng kể so với nhân viên toàn thời gian tiêu chuẩn.", "en_preferred": "Part-time worker", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": ['アルバイト'], "antonyms": [], "related_terms": ['扶養控除', '時給']},
    {"surface": "業務委託", "reading": "ぎょうむいたく", "vi_short": "khoán việc / làm việc tự do theo hợp đồng dịch vụ", "vi_explanation": "Hình thức hợp tác kinh tế cá nhân độc lập (Freelancer) không thiết lập quan hệ lao động chủ - thợ với công ty.", "en_preferred": "Outsourcing / Subcontracting", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['フリーランス', '源泉徴収']},
    {"surface": "試用期間", "reading": "しようきかん", "vi_short": "thời gian thử việc", "vi_explanation": "Giai đoạn đầu sau khi tuyển dụng (thường từ 3 đến 6 tháng) để công ty đánh giá phẩm chất và năng lực thực tế của nhân viên mới.", "en_preferred": "Probationary period", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['本採用', '試用期間満了']},
    {"surface": "労働条件通知書", "reading": "ろうどうじょうけんつうちしょ", "vi_short": "bản thông báo điều kiện làm việc bắt buộc", "vi_explanation": "Văn bản luật định công ty bắt buộc phải phát cho người lao động trước khi nhận việc, nêu rõ lương, giờ làm việc và địa điểm.", "en_preferred": "Notice of working conditions", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['雇用契約書', '労働基準法']},
    {"surface": "基本給", "reading": "きほんきゅう", "vi_short": "lương cơ bản", "vi_explanation": "Khoản tiền lương cốt lõi cố định hàng tháng chưa bao gồm phụ cấp chức vụ, tiền làm thêm giờ hoặc tiền thưởng.", "en_preferred": "Base salary / Basic pay", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['諸手当', '残業手当', '総支給額']},
    {"surface": "役職手当", "reading": "やくしょくてあて", "vi_short": "phụ cấp chức vụ quản lý", "vi_explanation": "Khoản tiền trợ cấp hàng tháng chi trả bổ sung cho người đảm nhiệm các vị trí lãnh đạo (Tổ trưởng, Trưởng phòng, Giám đốc).", "en_preferred": "Position allowance / Executive allowance", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['基本給', '管理職']},
    {"surface": "通勤手当", "reading": "つうきんてあて", "vi_short": "phụ cấp tiền tàu xe đi lại", "vi_explanation": "Khoản chi phí hỗ trợ tiền vé tàu hoặc xăng xe từ nhà đến nơi làm việc (được miễn thuế thu nhập cá nhân lên tới 15 vạn yên/tháng).", "en_preferred": "Commuting allowance", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['定期券', '非課税限度額']},
    {"surface": "残業手当", "reading": "ざんぎょうてあて", "vi_short": "tiền lương làm thêm giờ (Overtime)", "vi_explanation": "Khoản tiền trả thêm với hệ số tăng tối thiểu 25% cho thời gian làm việc vượt quá 8 tiếng/ngày hoặc 40 tiếng/tuần theo luật định.", "en_preferred": "Overtime allowance", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": ['時間外手当'], "antonyms": [], "related_terms": ['割増賃金', '36協定']},
    {"surface": "深夜手当", "reading": "しんやてあて", "vi_short": "phụ cấp làm việc ca đêm (22h đến 5h)", "vi_explanation": "Khoản tiền phụ cấp tăng thêm tối thiểu 25% tiền lương áp dụng cho những giờ làm việc rơi vào khung giờ đêm từ 22:00 đến 5:00 sáng.", "en_preferred": "Late-night work allowance", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['割増賃金', '深夜労働']},
    {"surface": "休日出勤手当", "reading": "きゅうじつしゅっきんてあて", "vi_short": "phụ cấp đi làm ngày nghỉ lễ theo luật định", "vi_explanation": "Khoản tiền lương trả tăng thêm với hệ số tối thiểu 35% khi nhân viên phải đi làm vào ngày nghỉ theo luật pháp quy định.", "en_preferred": "Holiday work allowance", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['法定休日', '振替休日']},
    {"surface": "固定残業代", "reading": "こていざんぎょうだい", "vi_short": "tiền làm thêm giờ khoán cố định (Minashi Zangyo)", "vi_explanation": "Chế độ trả trước một khoản tiền tương ứng với số giờ làm thêm cố định (ví dụ 30 giờ/tháng) gộp thẳng vào lương hàng tháng.", "en_preferred": "Fixed overtime pay", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:hr", "synonyms": ['みなし残業手当'], "antonyms": [], "related_terms": ['残業手当', '基本給']},
    {"surface": "裁量労働制", "reading": "さいりょうろうどうせい", "vi_short": "chế độ làm việc linh hoạt theo thỏa thuận kết quả", "vi_explanation": "Chế độ áp dụng cho công việc nghiên cứu hoặc thiết kế, người lao động tự chủ giờ giấc và được tính số giờ làm việc theo định mức.", "en_preferred": "Discretionary work system", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['みなし労働時間', '専門業務型']},
    {"surface": "変形労働時間制", "reading": "へんけいろうどうじかんせい", "vi_short": "chế độ thời gian làm việc biến đổi", "vi_explanation": "Chế độ tính giờ làm việc trung bình theo tháng hoặc năm, cho phép làm việc quá 8 giờ/ngày vào mùa cao điểm mà không tính tăng ca.", "en_preferred": "Variable working hours system", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['法定労働時間', 'シフト制']},
    {"surface": "有給休暇", "reading": "ゆうきゅうきゅうか", "vi_short": "nghỉ phép năm có hưởng lương", "vi_explanation": "Số ngày nghỉ phép được pháp luật bảo đảm cho người lao động đã làm việc đủ 6 tháng, doanh nghiệp bắt buộc phải cho nghỉ tối thiểu 5 ngày/năm.", "en_preferred": "Paid annual leave", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": ['有休'], "antonyms": ['欠勤'], "related_terms": ['年次有給休暇', '有休消化率']},
    {"surface": "特別休暇", "reading": "とくべつきゅうか", "vi_short": "nghỉ phép đặc biệt do công ty quy định", "vi_explanation": "Các ngày nghỉ phép hưởng lương do công ty tự đặt ra ngoài luật định như nghỉ kết hôn, nghỉ tang lễ người thân, nghỉ sinh nhật.", "en_preferred": "Special leave", "tier": "PRO-A1", "priority": 95, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['慶弔休暇', '有給休暇']},
    {"surface": "産前産後休業", "reading": "さんぜんさんごきゅうぎょう", "vi_short": "chế độ nghỉ thai sản trước và sau khi sinh", "vi_explanation": "Thời gian nghỉ sinh con được pháp luật bảo vệ gồm 6 tuần trước sinh và 8 tuần sau sinh, được quỹ bảo hiểm y tế chi trả trợ cấp.", "en_preferred": "Maternity leave", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:hr", "synonyms": ['産休'], "antonyms": [], "related_terms": ['出産手当金', '育児休業']},
    {"surface": "育児休業", "reading": "いくじきゅうぎょう", "vi_short": "chế độ nghỉ chăm con nhỏ (cho cả bố và mẹ)", "vi_explanation": "Thời gian nghỉ việc để chăm sóc con dưới 1 tuổi (có thể kéo dài đến 2 tuổi), được quỹ bảo hiểm thất nghiệp chi trả trợ cấp.", "en_preferred": "Childcare leave", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": ['育休'], "antonyms": [], "related_terms": ['育児休業給付金', '産後パパ育休']},
    {"surface": "介護休業", "reading": "かいごきゅうぎょう", "vi_short": "chế độ nghỉ chăm sóc người thân bị bệnh nặng", "vi_explanation": "Thời gian nghỉ việc tối đa 93 ngày để chăm sóc bố mẹ hoặc vợ chồng bị ốm đau nặng cần người chăm sóc lâu dài.", "en_preferred": "Nursing care leave", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['介護休業給付金', '介護保険']},
    {"surface": "社会保険", "reading": "しゃかいほけん", "vi_short": "bảo hiểm xã hội bắt buộc tại Nhật Bản", "vi_explanation": "Hệ thống bảo hiểm bao gồm Bảo hiểm Y tế và Bảo hiểm Lương hưu Phúc lợi, do doanh nghiệp và nhân viên cùng đóng mỗi bên 50%.", "en_preferred": "Social insurance", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['健康保険', '厚生年金保険', '社会保険料控除']},
    {"surface": "厚生年金保険", "reading": "こうせいねんきんほけん", "vi_short": "bảo hiểm lương hưu phúc lợi cho nhân viên công ty", "vi_explanation": "Chế độ lương hưu nhà nước bắt buộc dành cho nhân viên làm việc tại doanh nghiệp, đóng góp vào quỹ hưu trí để hưởng lương hưu tuổi già.", "en_preferred": "Employees' pension insurance", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:hr", "synonyms": ['厚生年金'], "antonyms": [], "related_terms": ['国民年金', '社会保険']},
    {"surface": "健康保険", "reading": "けんこうほけん", "vi_short": "bảo hiểm y tế quốc gia", "vi_explanation": "Bảo hiểm giúp người lao động và người thân chỉ phải chi trả 30% chi phí khám chữa bệnh và thuốc men tại bệnh viện.", "en_preferred": "Health insurance", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": ['健保'], "antonyms": [], "related_terms": ['健康保険証', '高額療養費']},
    {"surface": "雇用保険", "reading": "こようほけん", "vi_short": "bảo hiểm thất nghiệp", "vi_explanation": "Bảo hiểm chi trả trợ cấp thất nghiệp khi người lao động mất việc và tài trợ cho các khóa học nâng cao kỹ năng nghề nghiệp.", "en_preferred": "Employment insurance", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['失業手当', 'ハローワーク']},
    {"surface": "労災保険", "reading": "ろうさいほけん", "vi_short": "bảo hiểm tai nạn lao động (do công ty đóng 100%)", "vi_explanation": "Bảo hiểm bồi thường toàn bộ chi phí y tế và lương khi nhân viên bị tai nạn trong lúc làm việc hoặc trên đường đi làm.", "en_preferred": "Workers' accident compensation insurance", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": ['労働者災害補償保険'], "antonyms": [], "related_terms": ['労働災害', '通勤災害']},
    {"surface": "住民税特別徴収", "reading": "じゅうみんぜいとくべつちょうしゅう", "vi_short": "trừ thuế cư trú trực tiếp từ bảng lương hàng tháng", "vi_explanation": "Nghĩa vụ của doanh nghiệp phải khấu trừ tiền thuế cư trú từ lương của nhân viên từ tháng 6 đến tháng 5 năm sau để nộp về ủy ban quận/huyện.", "en_preferred": "Special collection of resident tax", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['普通徴収'], "related_terms": ['住民税', '給与天引き']},
    {"surface": "給与明細", "reading": "きゅうよめいさい", "vi_short": "bảng kê chi tiết tiền lương hàng tháng (Payslip)", "vi_explanation": "Bản chi tiết nêu rõ tổng thu nhập (lương cơ bản, phụ cấp), các khoản bị khấu trừ (thuế, bảo hiểm) và số tiền thực lĩnh chuyển khoản.", "en_preferred": "Salary statement / Payslip", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": ['給与明細書'], "antonyms": [], "related_terms": ['総支給額', '差引支給額', '控除額']},
    {"surface": "差引支給額", "reading": "さしひきしきゅうがく", "vi_short": "số tiền lương thực lĩnh vào tài khoản", "vi_explanation": "Số tiền lương ròng cuối cùng thực tế được chuyển khoản vào tài khoản ngân hàng của nhân viên sau khi đã trừ toàn bộ thuế và bảo hiểm.", "en_preferred": "Net pay / Take-home pay", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": ['手取り額'], "antonyms": ['総支給額'], "related_terms": ['控除額', '給与明細']},
    {"surface": "勤怠管理", "reading": "きんたいかんり", "vi_short": "quản lý chấm công và chuyên cần", "vi_explanation": "Hệ thống theo dõi giờ vào làm, giờ về, số ngày nghỉ phép, giờ làm thêm của toàn thể nhân viên trong công ty.", "en_preferred": "Attendance management", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['タイムカード', '出勤簿', '残業管理']},
    {"surface": "タイムカード", "reading": "たいむかーど", "vi_short": "thẻ chấm công / dữ liệu quẹt thẻ vào làm", "vi_explanation": "Công cụ ghi nhận chính xác thời điểm bắt đầu và kết thúc ngày làm việc của người lao động để làm căn cứ tính lương.", "en_preferred": "Time card / Punch card", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['打刻', '勤怠管理']},
    {"surface": "欠勤", "reading": "けっきん", "vi_short": "nghỉ làm không lương", "vi_explanation": "Việc người lao động không đến nơi làm việc vào ngày làm việc theo quy định (sẽ bị trừ tiền lương theo tỷ lệ ngày nghỉ).", "en_preferred": "Absence from work", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['出勤', '有給休暇'], "related_terms": ['ノーワーク・ノーペイ']},
    {"surface": "遅刻", "reading": "ちこく", "vi_short": "đi làm muộn", "vi_explanation": "Hành vi đến nơi làm việc sau giờ bắt đầu làm việc theo quy định của nội quy lao động.", "en_preferred": "Tardiness / Being late", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['早退', '定刻'], "related_terms": ['遅延証明書']},
    {"surface": "早退", "reading": "そうたい", "vi_short": "về sớm trước giờ quy định", "vi_explanation": "Hành vi rời khỏi nơi làm việc trước giờ kết thúc ngày làm việc vì lý do cá nhân hoặc bệnh đột xuất.", "en_preferred": "Leaving work early", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": ['遅刻'], "related_terms": ['早退届']},
    {"surface": "退職届", "reading": "たいしょくとどけ", "vi_short": "đơn xin thôi việc chính thức", "vi_explanation": "Văn bản do nhân viên tự nguyện nộp cho ban giám đốc để thông báo chính thức về việc xin chấm dứt hợp đồng lao động.", "en_preferred": "Letter of resignation", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:hr", "synonyms": ['退職願'], "antonyms": [], "related_terms": ['退職金', '退職手続']},
    {"surface": "懲戒解雇", "reading": "ちょうかいかいこ", "vi_short": "sa thải kỷ luật nặng nhất", "vi_explanation": "Hình thức đuổi việc nghiêm khắc nhất do nhân viên phạm tội hình sự, tham ô công quỹ hoặc gây tổn hại đặc biệt nghiêm trọng cho công ty.", "en_preferred": "Disciplinary dismissal", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:hr", "synonyms": [], "antonyms": [], "related_terms": ['解雇予告', '就業規則', '普通解雇']},
    {"surface": "整理解雇", "reading": "せいりかいこ", "vi_short": "sa thải cắt giảm nhân sự do suy thoái kinh tế", "vi_explanation": "Việc doanh nghiệp buộc phải cho nhân viên thôi việc tập thể do tình hình kinh doanh thua lỗ kéo dài (buộc phải đáp ứng 4 điều kiện khắt khe).", "en_preferred": "Redundancy dismissal / Restructuring layoff", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:hr", "synonyms": ['リストラ'], "antonyms": [], "related_terms": ['希望退職', '解雇規制']},
    {"surface": "退職金", "reading": "たいしょくきん", "vi_short": "tiền trợ cấp thôi việc một lần", "vi_explanation": "Khoản tiền thưởng tích lũy chi trả cho nhân viên khi nghỉ việc dựa trên số năm gắn bó cống hiến cho doanh nghiệp.", "en_preferred": "Retirement allowance / Severance pay", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:hr", "synonyms": ['退職手当'], "antonyms": [], "related_terms": ['退職所得控除', '確定拠出年金']},
    {"surface": "見込み客", "reading": "みこみきゃく", "vi_short": "khách hàng tiềm năng (Lead)", "vi_explanation": "Cá nhân hoặc tổ chức có nhu cầu hoặc sự quan tâm đến sản phẩm, dịch vụ và có khả năng sẽ mua hàng trong tương lai.", "en_preferred": "Prospective customer / Lead", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:sales", "synonyms": ['リード'], "antonyms": [], "related_terms": ['商談', '顧客開拓']},
    {"surface": "商談", "reading": "しょうだん", "vi_short": "buổi đàm phán thương mại / buổi trao đổi kinh doanh", "vi_explanation": "Cuộc họp hoặc cuộc trao đổi chính thức giữa nhân viên bán hàng và khách hàng nhằm giới thiệu sản phẩm và thương lượng hợp đồng.", "en_preferred": "Business negotiation / Sales meeting", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['アポイントメント', '提案書', '成約']},
    {"surface": "アポイントメント", "reading": "あぽいんとめんと", "vi_short": "cuộc hẹn làm việc trước", "vi_explanation": "Việc liên hệ trước qua điện thoại hoặc email để ấn định thời gian và địa điểm gặp gỡ trao đổi công việc với đối tác.", "en_preferred": "Appointment", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:sales", "synonyms": ['アポ'], "antonyms": [], "related_terms": ['商談', '訪問']},
    {"surface": "ヒアリング", "reading": "ひありんぐ", "vi_short": "khảo sát lắng nghe nhu cầu và vấn đề của khách hàng", "vi_explanation": "Kỹ năng đặt câu hỏi để nắm bắt chính xác hiện trạng, khó khăn và mong muốn của khách hàng trước khi đưa ra đề xuất giải pháp.", "en_preferred": "Customer hearing / Needs assessment", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['課題抽出', '提案書']},
    {"surface": "提案書", "reading": "ていあんしょ", "vi_short": "bản đề xuất giải pháp kinh doanh (Proposal)", "vi_explanation": "Tài liệu chi tiết phân tích vấn đề của khách hàng và trình bày phương án giải quyết kèm lộ trình triển khai và ngân sách.", "en_preferred": "Business proposal", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:sales", "synonyms": ['企画書'], "antonyms": [], "related_terms": ['プレゼンテーション', '商談']},
    {"surface": "プレゼンテーション", "reading": "ぷれぜんてーしょん", "vi_short": "thuyết trình chào hàng / trình bày phương án", "vi_explanation": "Buổi báo cáo trực tiếp sử dụng slide để thuyết phục khách hàng lựa chọn giải pháp hoặc mua sản phẩm của công ty.", "en_preferred": "Presentation / Pitch", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['プレゼン'], "antonyms": [], "related_terms": ['提案書', '質疑応答']},
    {"surface": "競合他社", "reading": "きょうごうたしゃ", "vi_short": "đối thủ cạnh tranh cùng ngành", "vi_explanation": "Các doanh nghiệp khác đang cung cấp các sản phẩm hoặc dịch vụ tương đương nhắm vào cùng một tập khách hàng mục tiêu.", "en_preferred": "Competitor / Rival company", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['ライバル企業'], "antonyms": [], "related_terms": ['差別化', '競合調査']},
    {"surface": "差別化", "reading": "さべつか", "vi_short": "tạo sự khác biệt độc đáo so với đối thủ", "vi_explanation": "Chiến lược làm cho sản phẩm, dịch vụ hoặc hình ảnh công ty trở nên nổi bật và ưu việt hơn so với các đối thủ trên thị trường.", "en_preferred": "Differentiation", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['強み', '優位性', '競合他社']},
    {"surface": "顧客満足度", "reading": "こきゃくまんぞくど", "vi_short": "chỉ số hài lòng của khách hàng (CS)", "vi_explanation": "Thước đo mức độ thỏa mãn của khách hàng đối với chất lượng sản phẩm, giá cả và dịch vụ chăm sóc khách hàng.", "en_preferred": "Customer satisfaction (CS)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['CS'], "antonyms": [], "related_terms": ['リピート率', 'アンケート調査']},
    {"surface": "リード獲得", "reading": "りーどかくとく", "vi_short": "thu hút dữ liệu khách hàng tiềm năng", "vi_explanation": "Các hoạt động tiếp thị như quảng cáo, hội thảo, triển lãm nhằm thu thập thông tin liên hệ của khách hàng tiềm năng.", "en_preferred": "Lead generation", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": ['リードジェネレーション'], "antonyms": [], "related_terms": ['見込み客', 'マーケティング']},
    {"surface": "クロージング", "reading": "くろーじんぐ", "vi_short": "chốt hợp đồng / bước ký kết đơn hàng", "vi_explanation": "Giai đoạn cuối cùng của quy trình bán hàng khi nhân viên thúc đẩy khách hàng đưa ra quyết định mua hàng chính thức.", "en_preferred": "Closing a deal", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['成約', '契約締結']},
    {"surface": "成約", "reading": "せいやく", "vi_short": "giao dịch thành công / chốt đơn thành công", "vi_explanation": "Việc khách hàng đồng ý ký kết hợp đồng hoặc gửi đơn đặt hàng mua sắm chính thức.", "en_preferred": "Closing a contract / Successful deal", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": ['失注'], "related_terms": ['成約率', '契約締結']},
    {"surface": "失注", "reading": "しっちゅう", "vi_short": "trượt đơn hàng / thua thầu", "vi_explanation": "Việc đàm phán bán hàng thất bại do khách hàng quyết định chọn nhà cung cấp đối thủ hoặc hủy bỏ dự án.", "en_preferred": "Lost order / Deal lost", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": ['成約', '受注'], "related_terms": ['敗因分析', '競合他社']},
    {"surface": "アフターサービス", "reading": "あふたーさーびす", "vi_short": "dịch vụ hậu mãi sau bán hàng", "vi_explanation": "Các hoạt động hỗ trợ kỹ thuật, sửa chữa, bảo hành và chăm sóc khách hàng sau khi đã bàn giao sản phẩm.", "en_preferred": "After-sales service", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": ['カスタマーサポート'], "antonyms": [], "related_terms": ['保証期間', '顧客満足度']},
    {"surface": "リピート率", "reading": "りぴーとりつ", "vi_short": "tỷ lệ khách hàng mua lại", "vi_explanation": "Tỷ lệ phần trăm khách hàng tiếp tục quay lại mua sắm sản phẩm hoặc tái ký hợp đồng dịch vụ sau lần đầu tiên.", "en_preferred": "Repeat purchase rate", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['リピーター', '解約率']},
    {"surface": "解約率", "reading": "かいやくりつ", "vi_short": "tỷ lệ hủy dịch vụ (Churn rate)", "vi_explanation": "Tỷ lệ khách hàng quyết định ngừng sử dụng dịch vụ hoặc không gia hạn hợp đồng phần mềm trong một khoảng thời gian.", "en_preferred": "Churn rate", "tier": "PRO-A2", "priority": 95, "source_reference": "trade_business_corpus:sales", "synonyms": ['チャーンレート'], "antonyms": [], "related_terms": ['リピート率', 'LTV']},
    {"surface": "顧客生涯価値", "reading": "こきゃくしょうがいかち", "vi_short": "giá trị trọn đời của khách hàng (LTV)", "vi_explanation": "Tổng số lợi nhuận ước tính mà một khách hàng đóng góp cho doanh nghiệp trong toàn bộ thời gian duy trì mối quan hệ hợp tác.", "en_preferred": "Customer Lifetime Value (LTV)", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:sales", "synonyms": ['LTV'], "antonyms": [], "related_terms": ['CAC', '顧客維持']},
    {"surface": "市場調査", "reading": "しじょうちょうさ", "vi_short": "nghiên cứu thị trường", "vi_explanation": "Việc thu thập và phân tích dữ liệu về quy mô ngành, xu hướng tiêu dùng và hành vi khách hàng để định hướng chiến lược.", "en_preferred": "Market research", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['マーケティングリサーチ'], "antonyms": [], "related_terms": ['ターゲット層', 'ニーズ']},
    {"surface": "ターゲット層", "reading": "たーげっとそう", "vi_short": "nhóm khách hàng mục tiêu", "vi_explanation": "Phân khúc khách hàng cụ thể có các đặc điểm chung về độ tuổi, thu nhập, ngành nghề mà sản phẩm tập trung phục vụ.", "en_preferred": "Target audience / Target demographic", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['市場調査', 'ペルソナ']},
    {"surface": "販路開拓", "reading": "はんろかいたく", "vi_short": "mở rộng kênh phân phối thị trường", "vi_explanation": "Chiến lược tiếp cận các thị trường mới hoặc ký hợp đồng với các đại lý bán lẻ mới để tăng doanh số bán hàng.", "en_preferred": "Sales channel development / Market expansion", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['代理店', '新規開拓']},
    {"surface": "代理店契約", "reading": "だいりてんけいやく", "vi_short": "hợp đồng đại lý phân phối", "vi_explanation": "Hợp đồng giao quyền cho một doanh nghiệp khác được phân phối bán sản phẩm của mình tại một khu vực địa lý cụ thể.", "en_preferred": "Distributorship agreement / Agency contract", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['代理店手数料', '総代理店']},
    {"surface": "フランチャイズ", "reading": "ふらんちゃいず", "vi_short": "nhượng quyền thương mại", "vi_explanation": "Mô hình cấp quyền kinh doanh cho đối tác sử dụng thương hiệu, bí quyết kinh doanh và hỗ trợ quản lý để thu phí nhượng quyền.", "en_preferred": "Franchise", "tier": "PRO-A1", "priority": 96, "source_reference": "trade_business_corpus:sales", "synonyms": ['FC'], "antonyms": [], "related_terms": ['ロイヤルティ', '加盟店']},
    {"surface": "協業", "reading": "きょうぎょう", "vi_short": "hợp tác kinh doanh cùng có lợi", "vi_explanation": "Sự bắt tay hợp tác giữa hai hay nhiều doanh nghiệp độc lập nhằm tận dụng thế mạnh công nghệ hoặc thị trường của nhau.", "en_preferred": "Business collaboration / Partnership", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['アライアンス'], "antonyms": [], "related_terms": ['提携', 'シナジー効果']},
    {"surface": "アライアンス", "reading": "あらいあんす", "vi_short": "liên minh chiến lược doanh nghiệp", "vi_explanation": "Mối quan hệ hợp tác chính thức giữa các công ty nhằm mở rộng quy mô kinh doanh mà không cần phải sáp nhập sở hữu.", "en_preferred": "Strategic alliance", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:sales", "synonyms": ['戦略的提携'], "antonyms": [], "related_terms": ['協業', '資本提携']},
    {"surface": "販売促進", "reading": "はんばいそくしん", "vi_short": "xúc tiến bán hàng / khuyến mãi (Sales Promotion)", "vi_explanation": "Các hoạt động kích thích mua hàng như giảm giá, tặng quà kèm, bốc thăm may mắn để thúc đẩy doanh thu nhanh chóng.", "en_preferred": "Sales promotion (SP)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['販促'], "antonyms": [], "related_terms": ['キャンペーン', '広告宣伝']},
