    {"surface": "価格交渉", "reading": "かかくこうしょう", "vi_short": "đàm phán giá cả mua bán", "vi_explanation": "Quá trình trao đổi thương lượng giữa bên mua và bên bán để đi đến mức giá đơn hàng mà cả hai bên cùng chấp nhận được.", "en_preferred": "Price negotiation", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['値引き', '相見積もり', 'コスト削減']},
