    {"surface": "売上目標", "reading": "うりあげもくひょう", "vi_short": "mục tiêu doanh thu / chỉ tiêu bán hàng", "vi_explanation": "Số tiền doanh số mà phòng kinh doanh hoặc cá nhân nhân viên bán hàng bắt buộc phải phấn đấu đạt được trong tháng hoặc quý.", "en_preferred": "Sales target / Revenue goal", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:sales", "synonyms": ['ノルマ'], "antonyms": [], "related_terms": ['予算達成率', 'KPI']},
    {"surface": "KPI", "reading": "けーぴーあい", "vi_short": "chỉ số đánh giá hiệu quả công việc cốt lõi", "vi_explanation": "Các chỉ số định lượng then chốt dùng để theo dõi tiến độ và đánh giá hiệu quả thực hiện các mục tiêu chiến lược.", "en_preferred": "Key Performance Indicator (KPI)", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:sales", "synonyms": ['重要業績評価指標'], "antonyms": [], "related_terms": ['KGI', '目標管理']},
    {"surface": "パイプライン管理", "reading": "ぱいぷらいんかんり", "vi_short": "quản lý phễu quy trình bán hàng", "vi_explanation": "Phương pháp theo dõi chi tiết từng giai đoạn của khách hàng từ tiếp xúc ban đầu, gửi báo giá đến chốt hợp đồng thành công.", "en_preferred": "Sales pipeline management", "tier": "PRO-A2", "priority": 94, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['営業進捗', '確度']},
