    {"surface": "受注残", "reading": "じゅうちゅうざん", "vi_short": "đơn hàng tồn đọng chưa bàn giao", "vi_explanation": "Tổng giá trị hoặc số lượng các đơn hàng mà công ty đã ký hợp đồng nhưng chưa sản xuất hoặc chưa giao hàng cho khách.", "en_preferred": "Order backlog / Backlog of orders", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:sales", "synonyms": [], "antonyms": [], "related_terms": ['受注高', '納期']},
    {"surface": "キーパーソン", "reading": "きーぱーそん", "vi_short": "người nắm quyền quyết định mua sắm cốt lõi", "vi_explanation": "Cá nhân trong tổ chức của khách hàng có tiếng nói quyết định cuối cùng trong việc phê duyệt ngân sách và lựa chọn nhà thầu.", "en_preferred": "Key decision maker", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['決裁権者'], "antonyms": [], "related_terms": ['商談', 'アプローチ']},
    {"surface": "紹介営業", "reading": "しょうかいえいぎょう", "vi_short": "bán hàng thông qua người quen giới thiệu", "vi_explanation": "Hình thức tiếp cận khách hàng mới nhờ sự kết nối và giới thiệu tin cậy từ những khách hàng cũ hoặc đối tác thân thiết.", "en_preferred": "Referral sales", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:sales", "synonyms": ['リファラル'], "antonyms": [], "related_terms": ['人脈', '新規開拓']},
    {"surface": "資金調達", "reading": "しきんちょうたつ", "vi_short": "gọi vốn đầu tư / huy động vốn", "vi_explanation": "Việc công ty tìm kiếm nguồn vốn từ ngân hàng, nhà đầu tư thiên thần hoặc quỹ đầu tư để mở rộng quy mô kinh doanh.", "en_preferred": "Fundraising / Financing", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['ベンチャーキャピタル', '借入金', '増資']},
    {"surface": "シード期", "reading": "しーどき", "vi_short": "giai đoạn hạt giống khởi nghiệp", "vi_explanation": "Giai đoạn sơ khai ban đầu của một công ty khởi nghiệp khi mới chỉ có ý tưởng hoặc sản phẩm thử nghiệm ban đầu.", "en_preferred": "Seed stage", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:operations", "synonyms": ['シードラウンド'], "antonyms": [], "related_terms": ['スタートアップ', 'エンジェル投資家']},
    {"surface": "ベンチャーキャピタル", "reading": "べんちゃーきゃぴたる", "vi_short": "quỹ đầu tư mạo hiểm (VC)", "vi_explanation": "Tổ chức chuyên đầu tư vốn cổ phần vào các công ty khởi nghiệp có tiềm năng tăng trưởng bùng nổ để kiếm lợi nhuận.", "en_preferred": "Venture Capital (VC)", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:operations", "synonyms": ['VC'], "antonyms": [], "related_terms": ['資金調達', '出資']},
    {"surface": "エンジェル投資家", "reading": "えんじぇるとうしか", "vi_short": "nhà đầu tư thiên thần", "vi_explanation": "Các cá nhân giàu có đầu tư vốn tự có của mình vào các công ty khởi nghiệp giai đoạn đầu để đổi lấy cổ phần sở hữu.", "en_preferred": "Angel investor", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['シード期', 'シード資金']},
    {"surface": "ピッチデック", "reading": "ぴっちでっく", "vi_short": "bộ slide thuyết trình gọi vốn khởi nghiệp", "vi_explanation": "Bản slide ngắn gọn (10-15 trang) tóm tắt mô hình kinh doanh, quy mô thị trường, đội ngũ và kế hoạch tài chính để thuyết phục nhà đầu tư.", "en_preferred": "Pitch deck", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:operations", "synonyms": ['ピッチ資料'], "antonyms": [], "related_terms": ['資金調達', 'プレゼンテーション']},
    {"surface": "ストックオプション", "reading": "すとっくおぷしょん", "vi_short": "quyền chọn mua cổ phiếu ưu đãi cho nhân viên", "vi_explanation": "Chính sách cho phép nhân viên có quyền mua một số lượng cổ phiếu của công ty với mức giá ưu đãi ấn định trước.", "en_preferred": "Stock options", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:operations", "synonyms": ['新株予約権'], "antonyms": [], "related_terms": ['インセンティブ', '上場']},
    {"surface": "バリュエーション", "reading": "ばりゅえーしょん", "vi_short": "định giá giá trị doanh nghiệp", "vi_explanation": "Phương pháp ước tính giá trị kinh tế của một công ty làm cơ sở để phát hành cổ phần khi huy động vốn đầu tư.", "en_preferred": "Company valuation", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:operations", "synonyms": ['企業価値評価'], "antonyms": [], "related_terms": ['時価総額', '資金調達']},
    {"surface": "バーンレート", "reading": "ばーんれーと", "vi_short": "tốc độ đốt tiền hàng tháng của startup", "vi_explanation": "Số tiền mặt ròng mà công ty khởi nghiệp tiêu hao mỗi tháng để chi trả cho các hoạt động vận hành trước khi có lãi.", "en_preferred": "Burn rate", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['ランウェイ', 'キャッシュフロー']},
    {"surface": "ランウェイ", "reading": "らんうぇい", "vi_short": "thời gian sống còn còn lại của startup", "vi_explanation": "Số tháng mà công ty có thể tiếp tục hoạt động với lượng tiền mặt hiện có trước khi cạn tiền nếu không gọi thêm vốn.", "en_preferred": "Runway", "tier": "PRO-A2", "priority": 92, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['バーンレート', '資金ショート']},
    {"surface": "業務効率化", "reading": "ぎょうむこうりつか", "vi_short": "tối ưu hóa hiệu suất công việc", "vi_explanation": "Việc loại bỏ các bước dư thừa lãng phí, tự động hóa quy trình để giảm chi phí và thời gian thực hiện công việc.", "en_preferred": "Operational efficiency / Streamlining operations", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['DX', '生産性向上']},
    {"surface": "デジタルトランスフォーメーション", "reading": "でじたるとらんすふぉーめーしょん", "vi_short": "chuyển đổi số doanh nghiệp (DX)", "vi_explanation": "Việc ứng dụng công nghệ kỹ thuật số vào toàn bộ quy trình kinh doanh nhằm nâng cao năng lực cạnh tranh và trải nghiệm khách hàng.", "en_preferred": "Digital Transformation (DX)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": ['DX'], "antonyms": [], "related_terms": ['IT化', 'クラウド導入']},
    {"surface": "テレワーク", "reading": "てれわーく", "vi_short": "làm việc từ xa / làm việc tại nhà", "vi_explanation": "Hình thức nhân viên làm việc tại nhà hoặc địa điểm linh hoạt thông qua mạng Internet thay vì phải đến công ty hàng ngày.", "en_preferred": "Telework / Remote work", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": ['リモートワーク', '在宅勤務'], "antonyms": [], "related_terms": ['ハイブリッドワーク', 'Web会議']},
    {"surface": "業務引き継ぎ", "reading": "ぎょうむひきつぎ", "vi_short": "bàn giao công việc khi chuyển công tác hoặc nghỉ việc", "vi_explanation": "Quy trình truyền đạt tài liệu, quy trình và hướng dẫn chi tiết cho người kế nhiệm để bảo đảm công việc không bị gián đoạn.", "en_preferred": "Handover of duties / Work transition", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": ['引き継ぎ'], "antonyms": [], "related_terms": ['引き継ぎ書', 'マニュアル']},
    {"surface": "情報セキュリティ", "reading": "じょうほうせきゅりてぃ", "vi_short": "an toàn an ninh thông tin", "vi_explanation": "Các biện pháp bảo vệ dữ liệu và hệ thống thông tin nội bộ của công ty khỏi các cuộc tấn công mạng, virus và rò rỉ dữ liệu.", "en_preferred": "Information security", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": ['情シス'], "antonyms": [], "related_terms": ['情報漏洩', 'アクセス権限']},
    {"surface": "個人情報保護法", "reading": "こじんじょうほうほごほう", "vi_short": "luật bảo vệ thông tin dữ liệu cá nhân", "vi_explanation": "Đạo luật của Nhật Bản quy định nghiêm ngặt về việc thu thập, lưu trữ và sử dụng họ tên, số điện thoại, dữ liệu của khách hàng.", "en_preferred": "Act on the Protection of Personal Information (APPI)", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['プライバシーポリシー', '情報漏洩']},
    {"surface": "プライバシーマーク", "reading": "ぷらいばしーまーく", "vi_short": "chứng nhận bảo mật thông tin cá nhân uy tín (P-Mark)", "vi_explanation": "Dấu chứng nhận cấp cho doanh nghiệp xây dựng hệ thống quản lý bảo vệ thông tin cá nhân đáp ứng tiêu chuẩn khắt khe của Nhật Bản.", "en_preferred": "PrivacyMark (P-Mark)", "tier": "PRO-A2", "priority": 93, "source_reference": "trade_business_corpus:operations", "synonyms": ['Pマーク'], "antonyms": [], "related_terms": ['個人情報保護法', '情報セキュリティ']},
    {"surface": "秘密保持誓約書", "reading": "ひみつほじせいやくしょ", "vi_short": "bản cam kết giữ bí mật thông tin của nhân viên", "vi_explanation": "Văn bản do nhân viên ký cam kết không bao giờ đem thông tin mật hoặc bí mật kinh doanh của công ty ra ngoài.", "en_preferred": "Confidentiality pledge / Non-disclosure pledge", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['秘密保持契約', '就業規則']},
    {"surface": "会議議事録", "reading": "かいぎぎじろく", "vi_short": "biên bản cuộc họp nội bộ", "vi_explanation": "Tài liệu ghi lại tóm tắt nội dung thảo luận, các quyết định thống nhất và các đầu việc cần làm (Action Items) sau cuộc họp.", "en_preferred": "Meeting minutes", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": ['議事録'], "antonyms": [], "related_terms": ['決定事項', 'ToDo']},
    {"surface": "業務フロー", "reading": "ぎょうむふろー", "vi_short": "sơ đồ quy trình luồng công việc", "vi_explanation": "Bản vẽ hoặc tài liệu mô tả tuần tự các bước thực hiện một công việc từ lúc bắt đầu cho đến khi hoàn thành.", "en_preferred": "Business workflow / Process flow", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": ['業務フロー図'], "antonyms": [], "related_terms": ['マニュアル', '標準化']},
    {"surface": "マニュアル作成", "reading": "まにゅあるさくせい", "vi_short": "biên soạn tài liệu hướng dẫn công việc chuẩn (SOP)", "vi_explanation": "Việc ghi chép chi tiết từng thao tác nghiệp vụ thành tài liệu chuẩn để bất kỳ ai cũng có thể đọc hiểu và thực hiện đồng nhất.", "en_preferred": "Creating manuals / SOP development", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": ['手順書'], "antonyms": [], "related_terms": ['標準化', '業務引き継ぎ']},
    {"surface": "予実管理", "reading": "よじつかんり", "vi_short": "quản lý so sánh giữa ngân sách kế hoạch và thực tế", "vi_explanation": "Việc theo dõi, đối chiếu liên tục giữa số liệu dự toán đề ra và kết quả thực tế phát sinh để kịp thời điều chỉnh kế hoạch.", "en_preferred": "Budget vs. actual management", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['予算', '実績', '差異分析']},
    {"surface": "経費精算", "reading": "けいひせいさん", "vi_short": "thủ tục thanh toán hoàn trả chi phí công tác", "vi_explanation": "Quy trình nhân viên nộp hóa đơn, phiếu thu để phòng kế toán kiểm tra và hoàn trả lại các khoản tiền đã ứng ra trả trước cho công ty.", "en_preferred": "Expense reimbursement / Expense settlement", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['領収書', '立替金', '仮払金']},
    {"surface": "立替精算", "reading": "たてかえせいさん", "vi_short": "quyết toán tiền chi hộ công ty", "vi_explanation": "Việc nhân viên nộp chứng từ đòi lại số tiền cá nhân đã chi trả trước thay cho công ty khi mua đồ dùng hoặc tiếp khách.", "en_preferred": "Reimbursement of out-of-pocket expenses", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['立替金', '経費精算']},
    {"surface": "出張申請", "reading": "しゅっちょうしんせい", "vi_short": "đơn đăng ký xin phê duyệt đi công tác", "vi_explanation": "Thủ tục xin cấp trên phê duyệt lịch trình, mục đích và dự toán kinh phí trước khi nhân viên đi công tác xa.", "en_preferred": "Business trip request / Travel authorization", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['出張報告書', '旅費規程']},
    {"surface": "直行直帰", "reading": "ちょっこうちょっき", "vi_short": "đi thẳng đến địa điểm gặp đối tác hoặc về thẳng nhà", "vi_explanation": "Việc nhân viên đi làm gặp khách hàng trực tiếp từ nhà buổi sáng hoặc kết thúc cuộc gặp xong về thẳng nhà không cần qua công ty.", "en_preferred": "Direct travel to/from client site", "tier": "PRO-A1", "priority": 99, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['外出', '勤怠報告']},
    {"surface": "朝礼", "reading": "ちょうれい", "vi_short": "cuộc họp giao ban ngắn đầu giờ sáng", "vi_explanation": "Buổi tập hợp toàn thể nhân viên phòng ban vào đầu giờ sáng (khoảng 5-10 phút) để chia sẻ thông báo và tạo tinh thần làm việc.", "en_preferred": "Morning meeting / Morning briefing", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": ['終礼'], "related_terms": ['共有事項', '定例会']},
    {"surface": "定例会議", "reading": "ていれいかいぎ", "vi_short": "cuộc họp định kỳ hàng tuần hoặc hàng tháng", "vi_explanation": "Cuộc họp được lên lịch cố định lặp lại để báo cáo tình hình tiến độ dự án và giải quyết các vướng mắc chung.", "en_preferred": "Regular meeting / Periodic meeting", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": ['定例会'], "antonyms": [], "related_terms": ['進捗確認', '議事録']},
    {"surface": "進捗報告", "reading": "しんちょくほうこく", "vi_short": "báo cáo cập nhật tiến độ công việc", "vi_explanation": "Hành động báo cáo cho quản lý và đồng nghiệp biết công việc hiện đã thực hiện được bao nhiêu phần trăm và có khó khăn gì không.", "en_preferred": "Progress report / Status update", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['報連相', 'スケジュール']},
    {"surface": "報連相", "reading": "ほうれんそう", "vi_short": "văn hóa Báo cáo - Liên lạc - Thảo luận (Ho-Ren-So)", "vi_explanation": "Quy tắc ứng xử và giao tiếp cơ bản nhất trong doanh nghiệp Nhật Bản: Báo cáo kết quả, Liên lạc thông tin kịp thời, và Thảo luận xin ý kiến.", "en_preferred": "Ho-Ren-So (Report-Communicate-Consult)", "tier": "PRO-A1", "priority": 100, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['報告', '連絡', '相談']},
