    {"surface": "社内規定", "reading": "しゃないきてい", "vi_short": "quy chế và quy định nội bộ công ty", "vi_explanation": "Toàn bộ hệ thống văn bản quy tắc hướng dẫn bắt buộc áp dụng cho toàn thể cán bộ nhân viên trong công ty.", "en_preferred": "Internal company regulations", "tier": "PRO-A1", "priority": 98, "source_reference": "trade_business_corpus:operations", "synonyms": ['社内ルール'], "antonyms": [], "related_terms": ['就業規則', 'コンプライアンス']},
    {"surface": "備品管理", "reading": "びひんかんり", "vi_short": "quản lý trang thiết bị đồ dùng văn phòng", "vi_explanation": "Việc theo dõi, cấp phát và bảo trì các thiết bị như máy in, máy tính, văn phòng phẩm để bảo đảm hoạt động vận hành trơn tru.", "en_preferred": "Equipment and supplies management", "tier": "PRO-A1", "priority": 97, "source_reference": "trade_business_corpus:operations", "synonyms": [], "antonyms": [], "related_terms": ['消耗品', '固定資産']},
